package com.ams.controller;
import com.ams.dto.TicketResponse; import com.ams.service.TicketService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/tickets") public class TicketController { private final TicketService service; public TicketController(TicketService service){this.service=service;} @GetMapping("/my") public ResponseEntity<List<TicketResponse>> mine(){return ResponseEntity.ok(service.getMyTickets());} @GetMapping("/number/{ticketNumber}") public ResponseEntity<TicketResponse> number(@PathVariable String ticketNumber){return ResponseEntity.ok(service.getByNumber(ticketNumber));} @GetMapping("/booking/{bookingId}") public ResponseEntity<List<TicketResponse>> booking(@PathVariable Integer bookingId){return ResponseEntity.ok(service.getByBooking(bookingId));} @GetMapping("/{ticketId}") public ResponseEntity<TicketResponse> id(@PathVariable Integer ticketId){return ResponseEntity.ok(service.getById(ticketId));} }
